mapper.select:
SELECT COUNT(*) FROM ai_evaluation e JOIN ai_task t ON t.owner_id=e.owner_id AND t.id=e.task_id
WHERE e.owner_id=#{owner} AND e.answer_id=#{answerId} AND t.status IN ('QUEUED','RUNNING','VALIDATING','CANCEL_REQUESTED')
AND e.task_id <> #{excludedTaskId}

SELECT t.id,t.purpose,t.status,t.revision,t.title,t.provider,t.model,t.currency,t.attempt_count,t.created_at,t.updated_at,t.error_code,
  e.question_id,e.answer_id,a.version_number AS answer_number
FROM ai_evaluation e JOIN ai_task t ON t.owner_id=e.owner_id AND t.id=e.task_id
JOIN training_answer a ON a.owner_id=e.owner_id AND a.session_id=e.session_id AND a.question_id=e.question_id AND a.id=e.answer_id
WHERE e.owner_id=#{owner} AND e.session_id=#{sessionId}
AND e.question_id=#{questionId}
AND t.id > #{cursor}
ORDER BY t.id LIMIT #{limit}
